MOD = 10**9 + 7

def solve(N: int) -> int:
    dp = [[0] * N for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]
            if i > 0 and j > 0 and i != j:
                dp[i][j] -= dp[i-1][j-1]

    total_paths = dp[N-1][N-1]
    for i in range(N):
        for j in range(N):
            if i > 0 or j > 0:
                total_paths += dp[i][j]

    transitions = total_paths - dp[N-1][N-1]
    prob = transitions % MOD

    return prob

